async function getMyCourses() {
  const response = await fetch(
    "/api/v1/me/courses",
    {
      method: "GET",
      headers: {
        "Authorization": `Bearer ${accessToken}`,
        "Accept": "application/json"
      }
    }
  );

  if (!response.ok) {
    throw new Error(
      `Request failed with status ${response.status}`
    );
  }

  return response.json();
}

function requestLogger(req, res, next) {
  const startedAt = Date.now();

  res.on("finish", () => {
    console.log({
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      durationMs: Date.now() - startedAt
    });
  });

  next();
}

async function getMyCourses(req, res, next) {
  try {
    const studentId = req.user.id;

    const courses = await courseService
      .getEnrolledCourses(studentId);

    res.status(200).json({
      success: true,
      data: courses
    });
  } catch (error) {
    next(error);
  }
}

async function getEnrolledCourses(studentId) {
  const enrollments = await enrollmentRepository
    .findActiveEnrollments(studentId);

  return enrollments.map((enrollment) => ({
    courseId: enrollment.course.id,
    title: enrollment.course.title,
    enrolledAt: enrollment.createdAt
  }));
}

